package com.tradereview.app.v200

import org.junit.Test
import org.junit.Assert.*
import java.math.BigDecimal
import java.time.LocalDate

class MatchingEngineTest {
    private val day=LocalDate.of(2025,1,2).toEpochDay()
    private fun stock(id:String,price:String="10",qty:String="100",date:Long=day,side:String="buy",fees:String="1")=LedgerExecution(id,"stock","600000","合成A股",date,600,date,0,side,if(side=="buy")"open"else"close",price,qty,fees)
    private fun future(id:String,price:String="3500",qty:String="2",date:Long=day,side:String="buy",effect:String="open",fees:String="2")=LedgerExecution(id,"futures","rb2701","螺纹钢",date,600,date,0,side,effect,price,qty,fees,multiplier="10",parametersConfirmed=true)
    private fun equal(expected:String,actual:String)=assertEquals(0,decimal(expected).compareTo(decimal(actual)))
    private fun rejects(block:()->Unit){try{block();fail("invalid facts accepted")}catch(_:LedgerException){}}
    @Test fun stockBuyAndFollowingDaySellUsesActualFees(){val s=MatchingEngine.replay(listOf(stock("a",fees="0.1"),stock("b","11",date=day+1,side="sell",fees="0.66")));equal("100",s.matches.single().gross);equal("99.24",s.matches.single().net);equal("0",s.cycles.single().remaining);equal("10",s.cycles.single().averagePrice)}
    @Test fun stockSameTradingDaySellingIsRejected(){rejects{MatchingEngine.replay(listOf(stock("a"),stock("b",side="sell")))}}
    @Test fun stockCannotSellUnknownOpeningHoldings(){rejects{MatchingEngine.replay(listOf(stock("b",side="sell")))}}
    @Test fun stockCannotOversell(){rejects{MatchingEngine.replay(listOf(stock("a"),stock("b",qty="101",date=day+1,side="sell")))}}
    @Test fun stockPartialSaleRetainsUnmatchedCost(){val r=MatchingEngine.replay(listOf(stock("a"),stock("b","11","40",day+1,"sell","0.4")));equal("60",r.lots.single().remaining);equal("0.4",r.lots.single().allocatedFees);equal("39.2",r.matches.single().net);equal("600.6",r.cycles.single().openCost)}
    @Test fun stockBoughtTodayCannotJoinOlderSellableBalance(){val r=MatchingEngine.replay(listOf(stock("a",qty="100"),stock("b",qty="100",date=day+1)));equal("100",exact(MatchingEngine.available(listOf(stock("a"),stock("b",date=day+1)),"stock","600000","sell",day+1,"close")));rejects{MatchingEngine.replay(listOf(stock("a"),stock("b",date=day+1),stock("c",qty="101",date=day+1,side="sell")))};assertEquals(2,r.lots.size)}
    @Test fun fifoAcrossMultipleStockBuyLots(){val r=MatchingEngine.replay(listOf(stock("a"),stock("b","20",fees="2"),stock("c","30","150",day+1,"sell","3")));equal("2495",exact(sum(r.matches.map{decimal(it.net)})));equal("50",r.cycles.single().remaining);equal("20",r.cycles.single().averagePrice);equal("1001",r.cycles.single().openCost)}
    @Test fun futuresLongProfitUsesOpeningMultiplier(){val r=MatchingEngine.replay(listOf(future("a"),future("b","3510","1",side="sell",effect="close",fees="3")));equal("100",r.matches.single().gross);equal("96",r.matches.single().net);equal("1",r.cycles.single().remaining)}
    @Test fun futuresShortProfit(){val r=MatchingEngine.replay(listOf(future("a",side="sell"),future("b","3490","1",side="buy",effect="close",fees="3")));equal("96",r.matches.single().net);assertEquals("short",r.cycles.single().direction)}
    @Test fun futuresLongAndShortNeverCrossMatch(){val r=MatchingEngine.replay(listOf(future("a"),future("b",side="sell")));assertEquals(2,r.cycles.size);rejects{MatchingEngine.replay(listOf(future("a"),future("c",side="buy",effect="close")))}}
    @Test fun futuresCloseTodayUsesOnlyTodayLots(){val r=MatchingEngine.replay(listOf(future("a"),future("b",date=day+1),future("c",qty="1",date=day+1,side="sell",effect="close_today")));assertEquals("b",r.matches.single().openExecutionId);equal("2",r.lots.first{it.executionId=="a"}.remaining)}
    @Test fun futuresCloseYesterdayCannotConsumeToday(){rejects{MatchingEngine.replay(listOf(future("a"),future("b",side="sell",effect="close_yesterday")))}}
    @Test fun futuresPartialYesterdayThenTodayPreservesCycle(){val r=MatchingEngine.replay(listOf(future("a"),future("b",date=day+1),future("c",qty="2",date=day+1,side="sell",effect="close_yesterday"),future("d",qty="1",date=day+1,side="sell",effect="close_today")));assertEquals(1,r.cycles.size);equal("1",r.cycles.single().remaining);assertEquals(setOf("a","b"),r.matches.map{it.openExecutionId}.toSet())}
    @Test fun fullCloseThenNewOpenCreatesNewStableCycle(){val r=MatchingEngine.replay(listOf(future("a"),future("b",date=day+1,side="sell",effect="close"),future("c",date=day+2)));assertEquals(setOf("cycle_a","cycle_c"),r.cycles.map{it.id}.toSet());assertEquals(day+1,r.cycles.first{it.id=="cycle_a"}.closedDay)}
    @Test fun decimalScaleDoesNotCreateZeroQuantityMatches(){val r=MatchingEngine.replay(listOf(stock("a",qty="1.0"),stock("b",qty="1.00",date=day+1,side="sell")));assertEquals(1,r.matches.size);equal("0",r.lots.single().remaining)}
    @Test fun feeAllocationConservesRepeatingDivisionAndFinalResidual(){val r=MatchingEngine.replay(listOf(stock("a",qty="3",fees="1"),stock("b",qty="1",date=day+1,side="sell",fees="0.1"),stock("c",qty="1",date=day+2,side="sell",fees="0.1"),stock("d",qty="1",date=day+3,side="sell",fees="0.1")));equal("1",exact(sum(r.matches.map{decimal(it.openFees)})));equal("0.3",exact(sum(r.matches.map{decimal(it.closeFees)})));equal("-1.3",exact(sum(r.matches.map{decimal(it.net)})))}
    @Test fun closeFeeSplitAcrossLotsIsNotRepeated(){val r=MatchingEngine.replay(listOf(stock("a",qty="1"),stock("b",qty="1"),stock("c",qty="2",date=day+1,side="sell",fees="7")));equal("7",exact(sum(r.matches.map{decimal(it.closeFees)})))}
    @Test fun unverifiedFuturesParametersCannotInventPnl(){rejects{MatchingEngine.replay(listOf(future("a").copy(multiplier=null,parametersConfirmed=false)))}}
    @Test fun differentOpeningAndClosingMultipliersAreRejected(){rejects{MatchingEngine.replay(listOf(future("a"),future("b",side="sell",effect="close").copy(multiplier="20")))}}
    @Test fun duplicateStableExecutionIdIsRejected(){rejects{MatchingEngine.replay(listOf(stock("a"),stock("a")))}}
    @Test fun stocksDefaultComprehensiveFeeRates(){equal("0.1",LedgerFees.stock("10","100","0.0001"));equal("0.66",LedgerFees.stock("11","100","0.0006"))}
    private fun rule()=LedgerContractRule("r","rb2701","合成参数",multiplier="10",openFee="2",closeFee="3",todayFee="10",effectiveDay=day,verified=true)
    @Test fun futuresPerLotExtraHasExplicitUnit(){equal("4.02",LedgerFees.futures(rule().copy(addMode="per_lot",addValue="0.01"),future("a"),emptyList()))}
    @Test fun futuresTurnoverAndPerTurnoverAdditionalAreExact(){equal("1.05",LedgerFees.futures(rule().copy(feeMode="turnover_rate",openFee="0.00001",closeFee="0.00002",todayFee="0.00003",addMode="turnover_rate",addValue="0.000005"),future("a"),emptyList()))}
    @Test fun mixedTodayYesterdayCloseCostsUseActualMatchedLots(){val prior=listOf(future("a"),future("b",date=day+1));equal("16",LedgerFees.futures(rule(),future("c",qty="3",date=day+1,side="sell",effect="close"),prior))}
    @Test fun feeAdditionalWithoutUnitIsRejected(){rejects{LedgerValidation.rule(rule().copy(addValue="0.01"))};rejects{LedgerValidation.rule(rule().copy(addMode="per_lot",addValue=null))}}
    @Test fun riskFundsAreIndependentFromAccountsAndOtherMarket(){val r=LedgerRisk.evaluate(stock("a",qty="200").copy(stopLoss="9"),MarketRisk("stock","10000","percent","1"));equal("200",r.amount!!);equal("2",r.percent!!);equal("100",r.limit!!);assertTrue(r.exceeded);val f=LedgerRisk.evaluate(future("b").copy(stopLoss="3490"),MarketRisk("futures","5000","percent","10"));equal("200",f.amount!!);equal("4",f.percent!!);assertFalse(f.exceeded)}
    @Test fun riskMissingStopHasNoFakeZero(){assertNull(LedgerRisk.evaluate(stock("a"),MarketRisk("stock")).amount);assertNull(LedgerRisk.evaluate(stock("a").copy(stopLoss="9"),MarketRisk("stock")).percent)}
    @Test fun longAndShortStopDirectionsAreValidated(){rejects{LedgerRisk.evaluate(future("a").copy(stopLoss="3501"),MarketRisk("futures"))};rejects{LedgerRisk.evaluate(future("a",side="sell").copy(stopLoss="3499"),MarketRisk("futures"))};equal("20",LedgerRisk.evaluate(future("a",side="sell").copy(stopLoss="3501"),MarketRisk("futures")).amount!!)}
    @Test fun marginOnlyUsesConfirmedParametersAndRemainingLots(){val r=MatchingEngine.replay(listOf(future("a").copy(marginRate="0.1"),future("b",qty="1",side="sell",effect="close")));equal("3500",r.cycles.single().referenceMargin!!);assertNull(MatchingEngine.replay(listOf(future("a"))).cycles.single().referenceMargin)}
    @Test fun referenceCashDoesNotSubtractRealizedFeesTwice(){val executions=listOf(stock("a",fees="0.1"),stock("b","11",date=day+1,side="sell",fees="0.66"));val replay=MatchingEngine.replay(executions);val state=LedgerSnapshot(executions=executions,lots=replay.lots,matches=replay.matches,cycles=replay.cycles,cashFlows=listOf(LedgerCashFlow("c","stock",day,"in","1000"),LedgerCashFlow("d","stock",day,"out","500")));equal("10599.24",LedgerStatistics.cash(state,LedgerAccount("stock","stock","A股","10000",true))!!);assertNull(LedgerStatistics.cash(state,LedgerAccount("stock","stock","A股","10000",false)));assertNull(LedgerStatistics.cash(state,LedgerAccount("futures","futures","期货","10000",true)))}
    @Test fun openOnlyExecutionsDoNotContributeRealizedStatistics(){val r=MatchingEngine.replay(listOf(stock("a")));assertTrue(LedgerStatistics.closed(LedgerSnapshot(executions=listOf(stock("a")),lots=r.lots,cycles=r.cycles)).isEmpty())}
    @Test fun nightTradeHasIndependentNaturalDateAndConfirmedTradingDay(){val e=future("night",date=day).copy(minute=21*60,tradingDay=day+1);val close=future("close",date=day+1,side="sell",effect="close_today");val r=MatchingEngine.replay(listOf(e,close));assertEquals(day+1,r.matches.single().day);assertEquals(day,e.date)}
    @Test fun unsupportedSecuritiesAreNotSilentlyTreatedAsNormalStock(){rejects{LedgerValidation.code("stock","510300")};rejects{LedgerValidation.code("stock","113001")}}
    @Test fun knownSecondsDetermineActualOrderRatherThanInputOrder(){val a=future("open").copy(second=5,ordinal=2);val b=future("close",side="sell",effect="close").copy(second=10,ordinal=1);val r=MatchingEngine.replay(listOf(b,a));assertEquals("open",r.matches.single().openExecutionId);assertEquals(listOf("open","close"),MatchingEngine.ordered(listOf(b,a)).map{it.id})}
    @Test fun unknownSecondsUseExplicitOrderAndNeverInventZeroSeconds(){val a=future("open").copy(second=null,ordinal=1,orderConfirmed=true);val b=future("close",side="sell",effect="close").copy(second=0,ordinal=2,orderConfirmed=true);assertEquals(listOf("open","close"),MatchingEngine.ordered(listOf(b,a)).map{it.id});assertEquals("open",MatchingEngine.replay(listOf(b,a)).matches.single().openExecutionId);rejects{MatchingEngine.replay(listOf(a.copy(ordinal=2),b.copy(ordinal=1)))}}
}
